    """Перед добавлением ограничения убирает точные дубли активных записей."""
    Booking = apps.get_model("core", "Booking")
    duplicates = (
        Booking.objects.filter(specialist__isnull=False)
        .exclude(status="canceled")
        .values("specialist_id", "start_at")
        .annotate(total=Count("id"))
        .filter(total__gt=1)
    )
    for group in duplicates:
        bookings = Booking.objects.filter(
            specialist_id=group["specialist_id"],
            start_at=group["start_at"],
        ).exclude(status="canceled")
        keep = bookings.order_by("created_at", "id").first()
        if keep is None:
            continue
        canceled = bookings.exclude(pk=keep.pk).update(status="canceled")
        if canceled:
            print(
                "P0-2: отменены дубли записи "
                f"specialist={group['specialist_id']} start_at={group['start_at']}: {canceled}"
            )


